import {renderDiagram} from './visual.js?v=20261023-physicscomplete01';
import {specialCellFigure,fateFigure} from './special-cell-figures.js?v=20261023-physicscomplete01';
import {specialCases,fateCases,comparedBoth,fateReady} from './special-cell-models.js?v=20261023-physicscomplete01';
import {escapeLab} from './catalog-labs.js?v=20261023-physicscomplete01';
export function showSpecial(type='sperm',w={}){const t=specialCases.find(t=>t.id===type)||specialCases[0];renderDiagram(t.name,t.job,specialCellFigure({type:t.id,adapted:w.adapted??true,step:w.step??0})+'<p class="diagram-caption">'+escapeLab(t.note)+'</p>','STRUCTURE → FUNCTION · SYMBOLIC MODEL');}
export function showFate(context='animal',w={}){const t=fateCases.find(t=>t.id===context)||fateCases[0];renderDiagram(t.title,['Starting cell','Developing structures','Specialised outcome'][w.stage??0],fateFigure({context:t.id,target:w.target||t.targets[0][0],stage:w.stage??0})+'<p class="diagram-caption">Model branches represent possible outcomes, not conscious choices or real developmental times. Restarting resets the illustration; it does not reverse differentiation.</p>','CELL DEVELOPMENT · SCHEMATIC');}
const options=(list,answer)=>'<option value="">Choose…</option>'+list.map(([value,label])=>'<option value="'+escapeLab(value)+'"'+(value===answer?' selected':'')+'>'+escapeLab(label)+'</option>').join('');
export function mountSpecialisation(l,p,root,{save,done,feedback}){
 const fate=l.widget==='cell-fate',tasks=fate?fateCases:specialCases,w=p.widget;w.task??=0;w.records??={};w.passed??=[];
 const t=tasks[w.task%tasks.length],r=w.records[t.id]??={};w.records[t.id]=r;const $=s=>root.querySelector(s);
 function finish(){if(!w.passed.includes(t.id))w.passed.push(t.id);if(w.passed.length===tasks.length){p.widgetDone=true;save();done();}save();$('#specialProgress').textContent=w.passed.length+' / '+tasks.length+' explained';}
 if(!fate){
  r.adapted??=false;r.step??=0;r.states??=[];
  root.innerHTML='<p><b>'+(w.task+1)+' / '+tasks.length+' · '+escapeLab(t.name)+'</b></p><p>'+escapeLab(t.job)+'. Predict the effect of the named adaptation, then step through both comparison states.</p><label class="field-label" for="specialPrediction">Adding '+escapeLab(t.feature.toLowerCase())+'…</label><select class="lab-select" id="specialPrediction">'+options(t.options,r.answer)+'</select><div class="model-actions"><button class="secondary" id="featureToggle" aria-pressed="'+r.adapted+'">'+(r.adapted?'Remove ':'Add ')+escapeLab(t.feature.toLowerCase())+'</button><button class="secondary" id="stepSpecial">Step model →</button></div><label class="field-label" for="specialStep">Scrub the symbolic process</label><input type="range" id="specialStep" min="0" max="6" step="1"><p class="micro-note" id="modelCompare"></p><button class="secondary" id="checkSpecial">Explain comparison</button><button class="secondary" id="nextSpecial">Next cell →</button><p id="specialProgress">'+w.passed.length+' / '+tasks.length+' explained</p>';
  const draw=()=>{showSpecial(t.id,r);$('#specialStep').value=r.step;$('#modelCompare').textContent='Model step '+r.step+' / 6 · '+(r.adapted?'Adaptation present':'Comparison without adaptation')+' · completed comparisons '+r.states.length+' / 2';};
  $('#specialPrediction').onchange=e=>{r.answer=e.target.value;save();};
  $('#featureToggle').onclick=()=>{r.adapted=!r.adapted;r.step=0;save();$('#featureToggle').textContent=(r.adapted?'Remove ':'Add ')+t.feature.toLowerCase();$('#featureToggle').setAttribute('aria-pressed',String(r.adapted));draw();};
  $('#specialStep').oninput=e=>{if(!r.answer){e.target.value=r.step;feedback('Make a prediction before scrubbing the model.',true);return;}r.step=Number(e.target.value);if(r.step===6&&!r.states.includes(r.adapted?'on':'off'))r.states.push(r.adapted?'on':'off');save();draw();};
  $('#stepSpecial').onclick=()=>{if(!r.answer){feedback('Make a prediction before stepping through the model.',true);return;}r.step=Math.min(6,r.step+1);if(r.step===6&&!r.states.includes(r.adapted?'on':'off'))r.states.push(r.adapted?'on':'off');save();draw();};
  $('#checkSpecial').onclick=()=>{if(!comparedBoth(r.states)){feedback('Take the model to its final step with the adaptation present and absent, then compare.',true);return;}if(r.answer!==t.effect){feedback('Reconsider the function. '+t.why,true);return;}feedback(t.why);finish();};draw();
 }else{
  r.target??=t.targets[0][0];r.stage??=0;r.paths??=[];
  root.innerHTML='<p><b>'+(w.task+1)+' / '+tasks.length+' · '+escapeLab(t.title)+'</b></p><p>'+escapeLab(t.question)+'</p><label class="field-label" for="fateTarget">Model outcome</label><select class="lab-select" id="fateTarget">'+t.targets.map(([id,label])=>'<option value="'+id+'"'+(r.target===id?' selected':'')+'>'+label+'</option>').join('')+'</select><div class="model-actions"><button class="secondary" id="stepFate">Develop model →</button><button class="secondary" id="restartFate">Restart illustration</button></div><p class="micro-note" id="fateProgress"></p><label class="field-label" for="fateReason">Explain what the comparison shows</label><select class="lab-select" id="fateReason">'+options(t.options,r.answer)+'</select><button class="secondary" id="checkSpecial">Check explanation</button><button class="secondary" id="nextSpecial">Next context →</button><p id="specialProgress">'+w.passed.length+' / '+tasks.length+' explained</p>';
  const draw=()=>{showFate(t.id,r);$('#fateProgress').textContent='Model stage '+r.stage+' / 2 · outcomes explored '+r.paths.length+' / '+t.targets.length;};
  $('#fateTarget').onchange=e=>{r.target=e.target.value;r.stage=0;save();draw();};$('#fateReason').onchange=e=>{r.answer=e.target.value;save();};
  $('#stepFate').onclick=()=>{r.stage=Math.min(2,r.stage+1);if(r.stage===2&&!r.paths.includes(r.target))r.paths.push(r.target);save();draw();};$('#restartFate').onclick=()=>{r.stage=0;save();draw();};
  $('#checkSpecial').onclick=()=>{if(!fateReady(t,r)){feedback('Develop each listed outcome to the final model stage, then explain the comparison.',true);return;}if(r.answer!==t.answer){feedback(t.why,true);return;}feedback(t.why);finish();};draw();
 }
 $('#nextSpecial').onclick=()=>{w.task=(w.task+1)%tasks.length;save();feedback('');mountSpecialisation(l,p,root,{save,done,feedback});};
}
